@c1 syntax.clause form=fragment complement=$n1
@r1 syntax.relation from=$n1 to=$n2

sop:
@n1 syntax.nominal head="what"
@n2 syntax.nominal head="I"
@c1 syntax.clause form=declarative verb="want" subject=$n2 complement=$n1
@c2 syntax.clause form=declarative verb="is" complement=$n3
@n3 syntax.nominal head="Review"
@c3 syntax.clause form=nonfinite verb="outlined"
@r1 syntax.relation marker="with" from=$c3 to=$n4
@n4 syntax.nominal head="dashes"
@r2 syntax.relation from=$c2 to=$c1
@r3 syntax.relation from=$n3 to=$c3

alt:
@n1 syntax.nominal head="what"
@n2 syntax.nominal head="I"
@c1 syntax.clause form=declarative verb="want" subject=$n2 complement=$n1
@c2 syntax.clause form=interrogative auxiliary="is" verb="outlined" subject=$n3
@n3 syntax.nominal head="Review"
@r1 syntax.relation marker="with" from=$c2 to=$n4
@n4 syntax.nominal head="dashes"
@r2 syntax.relation from=$c1 to=$c2
